        log(conn, "couple", "finish", {k: v for k, v in stats.items() if k != "judged_pairs"}, run_id)
        conn.execute("COMMIT")
    except BaseException:
        conn.execute("ROLLBACK")
        raise
    return {"run_id": run_id, **{k: v for k, v in stats.items() if k != "judged_pairs"}}

